def items3f(c):
    n=int(c[1:]); used=set(); out={}
    for t in range(1,7):
        L=L3F[t]; k=__import__('random').Random(f'item3f-{c}-{t}').randrange(10)
        for j in range(10):
            it,kind=L[(k+j)%10]
            if kind not in used: break
        used.add(kind); out[t]=(it,kind)
    return out
